<div class="box box-warning"><div class="box-header"><h3 class="box-title">Manifiesto de Carga de Encomiendas</h3></div><div class="box-body">
<form method="get" action=""><label>Seleccione viaje desde URL: encomienda/manifiesto/ID_VIAJE</label><select onchange="location='<?php echo site_url('encomienda/manifiesto'); ?>/'+this.value" class="form-control"><option>Seleccionar viaje</option><?php foreach($catalogos['viaje'] as $v){ ?><option value="<?php echo $v['viaje_id']; ?>" <?php echo ($viaje_id==$v['viaje_id'])?'selected':''; ?>>#<?php echo $v['viaje_id'].' '.$v['ruta_nombre'].' '.$v['viaje_fechasalida'].' '.$v['vehiculo_placa']; ?></option><?php } ?></select></form><hr>
<?php if($viaje_id){ ?><div class="text-right"><a href="<?php echo site_url('encomienda/despachar/'.$viaje_id); ?>" class="btn btn-danger"><i class="fa fa-truck"></i> Confirmar despacho</a> <a target="_blank" href="<?php echo site_url('encomienda/imprimir_manifiesto/'.$viaje_id); ?>" class="btn btn-primary"><i class="fa fa-print"></i> Imprimir manifiesto</a></div><br>
<table class="table table-bordered table-striped"><thead><tr><th>#</th><th>Guía</th><th>Destinatario</th><th>Contenido</th><th>Peso</th><th>Total</th><th>Estado</th></tr></thead><tbody><?php $i=1;$peso=0;$total=0; foreach($encomiendas as $e){ $peso+=$e['encomienda_peso']; $total+=$e['encomienda_total']; ?><tr><td><?php echo $i++; ?></td><td><?php echo $e['encomienda_guia']; ?></td><td><?php echo $e['encomienda_destinatarionombre']; ?></td><td><?php echo $e['encomienda_contenido']; ?></td><td><?php echo $e['encomienda_peso']; ?></td><td><?php echo number_format($e['encomienda_total'],2); ?></td><td><?php echo $e['encomiendaestado_nombre']; ?></td></tr><?php } ?></tbody><tfoot><tr><th colspan="4">Totales</th><th><?php echo number_format($peso,2); ?> Kg</th><th><?php echo number_format($total,2); ?></th><th></th></tr></tfoot></table><?php } ?>
</div></div>
